    [Fact] public void Declarations_and_producers_never_upgrade_to_live_observations()
    {
        var f=new WorldNormalFixture();var e=f.Entry();Assert.False(e.CurrentActorObserved);Assert.False(e.World.CurrentWorldObserved);
        Assert.Empty(typeof(W.Entry).GetConstructors());Assert.Empty(typeof(W.Scene).GetConstructors());
        Assert.Empty(typeof(O.GuardAdmission).GetConstructors());Assert.Empty(typeof(O.ImpactAdmission).GetConstructors());
        Assert.Empty(typeof(F.OwnedImpact).GetConstructors());Assert.Empty(typeof(F.HpAdmission).GetConstructors());
    }
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]
    public void Exact_source_context_evidence_and_owned_complete_registry_are_admission_requirements(int gap)
    {
