    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)]
    public void Raw_HP_world_and_manager_lifetime_joins_fail_before_any_published_prefix(int gap)
    {
        var f=new WorldNormalFixture();switch(gap)
        {
            case 0:f.Raw.W32(WorldNormalFixture.User+0x778,4999);break;
            case 1:f.Raw.W64(WorldNormalFixture.User+0x118,0);break;
            case 2:f.Hp=f.Hp with{Guards=f.Hp.Guards with{Manager=f.Hp.Guards.Manager with{Generation="stale"}}};break;
            case 3:f.Raw.Forget(WorldNormalFixture.User+0x5b24,4);break;
            case 4:f.Hp=f.Hp with{Receiver=f.Hp.Receiver with{Telemetry=f.Hp.Receiver.Telemetry with{Level1492=54}}};break;
        }
        var result=O.EvaluateWorld(f.Entry());Assert.Null(result.Calculated);Assert.Null(result.Emission);Assert.NotNull(result.Failure);
