    [Fact] public void Native_guard_rejection_preserves_calculated_preparation_without_RNG_or_HP()
    {
        var f=new WorldNormalFixture();f.Raw.W8(WorldNormalFixture.User+0x731b,1);f.Hp=f.Hp with{Receiver=f.Hp.Receiver with{Raw=f.Hp.Receiver.Raw with{Protection731b=1}}};
        var e=f.Entry();e=W.Entry.Declare(e.Record,e.HpCurrent,e.Gear,e.World,e.Clocks.Take(2).ToImmutableArray(),e.Budget,50,7,e.Receipt);
        var result=O.EvaluateWorld(e);Assert.Equal(O.Status.NativeTargetRejectedPrepared,result.Status);Assert.NotNull(result.Calculated);
