        Assert.Equal(f.Record.Selected.Element,new U.Cursor(e.Record.Context.Common,result.Calculated!,100).I32(WorldNormalFixture.Npc+0x8f4,0,"prepared element"));
        Assert.Equal(5000,WorldNormalFixture.I32(result.Calculated!,WorldNormalFixture.User+0x778));
