    public static IEnumerable<object[]> State17Rows()=>Enumerable.Range(0,15).SelectMany(x=>new[]{0,0x10}.Select(flags=>new object[]{x,flags}));
    [Theory][MemberData(nameof(State17Rows))]
    public void All15_pinned_event17_rows_compute_writes_and_CanAttack_ignores_the_state_return(int pose,int flags)
    {
        var f=new WorldNormalFixture();f.Raw.W32(WorldNormalFixture.Npc+0x13c,(uint)(pose|flags));var r=O.GuardAdmission.Calculate(f.Entry());
        Assert.NotNull(r.Value);Assert.Null(r.Failure);Assert.False(r.NativeRejected);
        bool writes=flags==0&&pose is 1 or 2 or 3 or 4 or 11 or 14;
        Assert.Equal(writes?1:0,r.Work!.Steps.Count(x=>x.Kind=="Write"&&x.Operand=="Npc.event17.pose_write"));
        Assert.Equal(pose|flags,r.Work.Cursor.I32(WorldNormalFixture.Npc+0x13c,0,"calculated pose"));
    }
