    [Fact] public void Nonlethal_entry_does_not_consume_SourceWorld_or_User_log_operands()
    {
        var f=new WorldNormalFixture();f.Hp=f.Hp with{SourceWorld=new(H.Presence.Unknown,null,new(N.FactKind.Unknown,"unreached")),
            Receiver=f.Hp.Receiver with{Log=new(uint.MaxValue,int.MinValue,"unread label","unread account",int.MinValue,int.MaxValue,new(N.FactKind.Unknown,"unreached"))}};
        foreach(int offset in new[]{0x79c,0x584c,0x3a70,0x7254,0x70bc,0x70da})f.Raw.Forget(WorldNormalFixture.User+(ulong)offset,4);
        var r=O.EvaluateWorld(f.Entry());Assert.Equal(O.Status.CalculatedImmediateWorld,r.Status);Assert.Null(r.Failure);
        Assert.DoesNotContain(r.Steps,x=>x.Operand.StartsWith("telemetry.",StringComparison.Ordinal));
        Assert.Empty(r.Completion!.Hp!.Owner.Events.OfType<H.UserDeathTelemetry>());
    }
    [Fact] public void Known_early_UTF16_terminators_do_not_require_later_unknown_code_units()
    {
        var f=new WorldNormalFixture("whole150_lethal_preview");
        f.Raw.Forget(WorldNormalFixture.User+0x70be,2);f.Raw.Forget(WorldNormalFixture.User+0x70dc,2);
        var r=O.EvaluateWorld(f.Entry());Assert.Equal(O.Status.CalculatedImmediateWorld,r.Status);Assert.Null(r.Failure);
        Assert.DoesNotContain(r.Steps,x=>x.Operand is "telemetry.User.account70bc[1]" or "telemetry.User.label70da[1]");
        Assert.All(r.Completion!.Hp!.Owner.Events.OfType<H.UserDeathTelemetry>(),x=>{Assert.Equal("",x.User.Label70da);Assert.Equal("",x.User.Account70bc);});
    }
    [Theory][InlineData("","")][InlineData(" \t"," \r\n")][InlineData("A","B")]
    public void Private_World_log_admission_preserves_exact_native_UTF16_without_trimming(string label,string account)
