    [Fact] public void Inline_UTF16_retains_an_unpaired_surrogate_code_unit_without_replacement()
    {
        var f=new WorldNormalFixture("whole150_lethal_preview");string unit=new(new[]{(char)0xd800});f.NativeText(0x70da,unit);
        f.Hp=f.Hp with{Receiver=f.Hp.Receiver with{Log=f.Hp.Receiver.Log with{Label70da=unit}}};
        var r=O.EvaluateWorld(f.Entry());Assert.Equal(O.Status.CalculatedImmediateWorld,r.Status);Assert.Null(r.Failure);
        Assert.All(r.Completion!.Hp!.Owner.Events.OfType<H.UserDeathTelemetry>(),x=>Assert.Equal((char)0xd800,Assert.Single(x.User.Label70da)));
