    [Fact] public void Missing_UTF16_terminator_at_the_explicit_adapter_bound_is_not_an_empty_label()
    {
        var f=new WorldNormalFixture("whole150_lethal_preview");
        for(int i=0;i<256;i++)f.Raw.W16(WorldNormalFixture.User+0x70da+(ulong)(2*i),(ushort)'a');
        // This range also contains7254: join its exact resulting numeric word first.
        f.Hp=f.Hp with{Receiver=f.Hp.Receiver with{Log=f.Hp.Receiver.Log with{Log7254=0x00610061,Label70da=new string('a',256)}}};
        var entry=f.Entry();
        var child=Assert.Throws<U.Domain>(()=>W.JoinReachedUserLog(new W.Work(entry),entry.HpCurrent.Receiver.Log));
        Assert.Equal("capacity",child.Failure.Code);Assert.Equal("telemetry.User.label70da",child.Failure.Operand);
        Assert.Equal(0x140542221ul,child.Failure.Site);
        var r=O.EvaluateWorld(entry);Assert.Equal(O.Status.IncompleteAtChild,r.Status);
        Assert.Null(r.Calculated);Assert.Null(r.Completion);Assert.Null(r.Emission);Assert.Empty(r.RandomCalls);Assert.Empty(r.Steps);
        Assert.Equal("completion",r.Failure!.Code);Assert.Equal(child.Failure.Operand,r.Failure.Operand);
        Assert.Equal(child.Failure.Detail,r.Failure.Detail);
    }
    [Fact] public void Lethal_log_numeric_channels_keep_unsigned_ID_signed_character_and_native_tail_cast()
    {
        var f=new WorldNormalFixture("whole150_lethal_preview");f.Raw.W32(WorldNormalFixture.User+0x7254,uint.MaxValue);
        f.Raw.W32(WorldNormalFixture.User+0x3a70,0x80000000);f.Raw.W32(WorldNormalFixture.User+0x584c,uint.MaxValue);f.Raw.W32(WorldNormalFixture.User+0x79c,0x80000000);
        f.Hp=f.Hp with{Receiver=f.Hp.Receiver with{Log=f.Hp.Receiver.Log with{Log7254=uint.MaxValue,Character3a70=int.MinValue,Field584c=-1,Field79c=int.MinValue}}};
        var r=O.EvaluateWorld(f.Entry());Assert.Equal(O.Status.CalculatedImmediateWorld,r.Status);Assert.Null(r.Failure);
        var e=Assert.Single(r.Completion!.Hp!.Owner.Events.OfType<H.UserDeathTelemetry>(),x=>x.EventId==0x8b);
        Assert.Equal(uint.MaxValue,e.User.Log7254);Assert.Equal(int.MinValue,e.User.Character3a70);
        Assert.Equal(4294967295L,e.NativeTail[2]);Assert.Equal((long)int.MinValue,e.NativeTail[3]);
    }
    [Fact] public void A_native_null_SourceWorld_helper_skips_unreached_map_word()
    {
        // The whole World entry requires current nonnull membership. This helper-only
        // vector proves the native null branch without admitting that invalid whole scene.
        var f=new WorldNormalFixture();f.Raw.W64(WorldNormalFixture.Npc+0x118,0);f.Raw.Forget(WorldNormalFixture.World+0x20,4);var w=new W.Work(f.Entry());
        Assert.Equal(0u,W.JoinReachedSourceWorld(w,new(H.Presence.VerifiedNull,null,WorldNormalFixture.Evidence)));
        Assert.DoesNotContain(w.Steps,x=>x.Operand=="telemetry.Npc.World.map20");
        Assert.Null(O.EvaluateWorld(f.Entry()).Calculated);
    }

