internal sealed class WorldNormalFixture
{
    internal const ulong Npc=NormalRecordFixture.Npc,User=NormalRecordFixture.User,Template=NormalRecordFixture.Template,
        Manager=NormalRecordFixture.Manager,Frame=NormalRecordFixture.Frame,World=0x90000000,Connection=0x77000000;
    internal static readonly N.Evidence Evidence=new(N.FactKind.SourceBoundDeclaration,"constructed whole World fixture; not native execution");
    internal static JsonDocument Corpus{get;}=Load();
    internal JsonElement Row{get;} internal NormalRecordFixture Raw{get;}
    internal C.Input Record=>Raw.Input(); internal H.Input Hp;
    internal GI.Input Gear;internal W.Limits Limits=new(60000,128,40,1000,60000);
    internal ImmutableArray<W.UserRoot> Roots;
    internal WorldNormalFixture(string name="whole100_charge_refresh"):this(Corpus.RootElement.GetProperty("cases").EnumerateArray().Single(x=>x.GetProperty("name").GetString()==name)){ }
    internal WorldNormalFixture(int index):this(Corpus.RootElement.GetProperty("cases")[index]){ }
    private WorldNormalFixture(JsonElement row)
    {
        Row=row;Raw=new(row.GetProperty("normal"));var (hp,gear)=RetailNpcToUserImmediateDamageOwnerTests.WorldCurrentFixture(1);
        int template=Raw.Projection.NpcId;var scope=RetailNpcNormalScope.Create(RetailNpcNormalScope.MainBinarySha256,
            RetailNpcNormalActorKind.OrdinaryOwnerlessNpc,RetailNpcNormalActorKind.Player,template,0);
        Raw.Context=Raw.Context with{Common=Raw.Context.Common with{Operation=hp.Source.Operation,Epoch=hp.Source.Epoch}};
        Raw.Clocks=Raw.Clocks.Select(x=>x with{Operation=hp.Source.Operation,Epoch=hp.Source.Epoch}).ToImmutableArray();
        int current=row.GetProperty("recipe").GetProperty("current_HP").GetInt32();
        ushort level=(ushort)row.GetProperty("normal").GetProperty("expected").GetProperty("inputs").GetProperty("source_level").GetInt32();
        Hp=hp with{Scope=scope,Attacker=hp.Attacker with{Binding=hp.Attacker.Binding with{TemplateId=template},
            Telemetry=hp.Attacker.Telemetry with{LogId100=(uint)template,Level1492=level,Position120=new(Bits(10),Bits(20),Bits(30))}},
            Receiver=hp.Receiver with{State=hp.Receiver.State with{Hp778=current},Raw=hp.Receiver.Raw with{FirstDeathKind5b24=77}},
            Guards=hp.Guards with{Manager=hp.Guards.Manager with{Pointer158=Manager}}};

        // Append-only F02 overlay f910f671...: this row's retained raw bank contains
        // four numeric zeros and known empty UTF16 strings, rather than Make's labels.
        if(row.GetProperty("name").GetString()=="whole150_lethal_preview")
            Hp=Hp with{Receiver=Hp.Receiver with{Log=new(0,0,"","",0,0,Hp.Receiver.Log.Evidence)}};
        Gear=gear with{Scope=scope,Life=gear.Life with{Hp=current}};Roots=[Root()];
    }

    internal void NativeText(ulong offset,string text)
    {
        for(int i=0;i<text.Length;i++)Raw.W16(User+offset+(ulong)(2*i),text[i]);
        Raw.W16(User+offset+(ulong)(2*text.Length),0);
    }
    internal void MpShield(int amount=60,int budget=1000,int mode=0)
    {
        ulong row=Manager+(1ul+0x23c)*20;
        Raw.W32(Manager+0x2b18,0x800);Raw.W32(row,1000);Raw.W32(row+4,unchecked((uint)amount));Raw.W32(row+8,(uint)mode);
        Raw.W32(row+12,1234);Raw.W32(row+16,50);Raw.W32(Manager+0x2d00,(uint)budget);Raw.W32(Manager+0x2d04,25);
        Hp=Hp with{Guards=Hp.Guards with{Manager=Hp.Guards.Manager with{Flags2b18=0x800}}};
    }
    internal W.UserRoot Root()=>new(User,"user-life",0,0,0,Connection,"connection-generation","current-client-3720");
    internal W.Clock Clock(W.Phase phase,string role,ulong caller,ulong site,ulong actor,uint value=1000,string? life=null)=>new(phase,role,caller,site,actor,
        life??(actor==Npc?"source-life":actor==World?"world-generation":"user-life"),value,Raw.Context.Common.Operation,Raw.Context.Common.Epoch,"constructed original-site clock");
    internal ImmutableArray<W.Clock> HpClocks(bool lethal=false)
    {
        var list=new List<W.Clock>{Clock(W.Phase.Hp,"CancelCombine",0,0x14031a3d1,User),Clock(W.Phase.Hp,"AttributionOuter",0,0x1402a740c,User),Clock(W.Phase.Hp,"PostHit",0,0x140541fda,User)};
        if(lethal)list.AddRange([Clock(W.Phase.Hp,"TimerEntry",0,0x140d01b02,User),Clock(W.Phase.Hp,"TimerDue",0,0x140d01c29,User),Clock(W.Phase.Hp,"TimerExit",0,0x140d01da2,User)]);
        return [..list];
    }
    internal W.Entry Entry(ushort duration=50,ImmutableArray<W.Clock>? clocks=null)
    {
        var record=Record;var all=new List<W.Clock>{Clock(W.Phase.Position,"NpcPosition",0x14068f2b6,0x140b1802e,Npc),Clock(W.Phase.Position,"UserPosition",0x14068f2c7,0x1400d1b10,User)};
        all.AddRange(Raw.Clocks.Select(x=>Clock(W.Phase.Normal,x.Role.ToString(),x.CallerSite,x.TickSite,User,x.Value)));
        all.Add(Clock(W.Phase.Late,"FinalMovement",0x14068fb1b,0x140578ec9,User));all.Add(Clock(W.Phase.Late,"WorldActivity",0x14068fd43,0x14068fd43,User));
        if(duration<=50)all.AddRange(HpClocks(Row.GetProperty("expected").GetProperty("pending728").GetInt32()!=0));
        else all.Add(Clock(W.Phase.Late,"ManagedImpactSchedule",0,0,World));
        return Declare(record,Hp,Gear,duration,clocks??all.ToImmutableArray());
    }
    internal W.Entry Declare(C.Input record,H.Input hp,GI.Input gear,ushort duration,ImmutableArray<W.Clock> clocks)
    {
        var world=W.Scene.DeclareComplete(record.Context.Common,World,"world-generation","serialized-world","revision1","constructed complete current cell registry",Roots,128);
        var owned=H.OwnedGearSnapshot.Admit(gear,H.OwnedClassRecipe.Gladiator55NativePermit1JavaOrdinal1,Evidence);
        return W.Entry.Declare(record,hp,owned,world,clocks,Limits,duration,7,"independent raw World fixture");
    }
    internal W.Entry FreshDispatch(O.Result created,uint now=1001,bool retarget=false)
    {
        Assert.NotNull(created.Calculated);var record=Record with{Memory=created.Calculated!,Random=Raw.Random with{InitialGeneration=created.RandomGenerationAfter!.Value,
            InitialStateBytes=created.RandomStateAfter!.Bytes,InitialStateSha256=created.RandomStateAfter.Sha256,
            Ownership=Raw.Random.Ownership! with{InitialGeneration=created.RandomGenerationAfter.Value}}};
        if(retarget){var c=new U.Cursor(record.Context.Common,record.Memory,100);c.W32(Npc+0x13d4,0x12345678,0,"new current target");record=record with{Memory=c.Snapshot()};}
        var hp=Hp with{Receiver=Hp.Receiver with{State=Hp.Receiver.State with{Pending728=I32(record.Memory,User+0x728)},Raw=Hp.Receiver.Raw with{ActivityDue42cc=11000}}};
        var clocks=ImmutableArray.Create(Clock(W.Phase.Late,"ManagedImpactDispatch",0,0,World,now)).AddRange(HpClocks(Row.GetProperty("expected").GetProperty("pending728").GetInt32()!=0));
        return Declare(record,hp,Gear,50,clocks);
